 /**
 * Die Klasse Spiel startet das Spiel und reagiert auf Tastatureingaben.
 * 
 * @author Klaus Dingemann 
 * @version 19.02.17
 */

import java.awt.Color;
import sas.*;
import sasio.*;
public class SillyBird
{   
    final static String DATEINAME = "sillybird.txt";
    private View view;
    private Landschaft landschaft;
    private Vogel vogel;
    private int punkte;
    private Text ausgabePunkte;


    public SillyBird() {
         view = new View(800, 600, "Vogel flieg");
         punkte = 0;
         landschaft = new Landschaft();
         vogel = new Vogel();
         ausgabePunkte = new Text(5, 20,"Punkte: 0", Color.RED);
    }

    /**
     * Laeuft solange, bis das Spiel mit ESC unterbrochen wurde oder der 
     * Vogel mit einem Hindernis kollidiert ist.
     * 
     */
    public void spielen() 
    {        
        int weiter = 1;
        do {
          boolean spielBeendet = false;
          view.wait(2000);
          while(!spielBeendet) {
            landschaft.bewegen(-2);
            vogel.bewegen(7);
            if(view.keyUpPressed()){
              vogel.bewegen(-12);
            } 
            if (landschaft.kollision(vogel)) {
              spielBeendet = true;
            } else if (landschaft.hindernisPassiert(vogel)) {
                punkte = punkte + 1;
                zeigePunktestand();
            }
            view.wait(30);
         }
         weiter = Tools.confirmDialog("Noch ein Spiel");
          if (weiter==0) {
            this.ausgangsposition();
            spielBeendet = false;
          }
        } while (weiter==0);
        System.exit(0);
    }

    public void ausgangsposition() {
       view.keyBufferDelete();
       vogel.setzeInAusgangsposition();
       landschaft.setzeInAusgangsposition();
       punkte = 0;
       zeigePunktestand();
    }

    public void zeigePunktestand() {
            ausgabePunkte.setText("Punkte: "+punkte);
     }





    static void main(String[] args){
       SillyBird vf = new SillyBird();
       vf.spielen();
    }
}

import java.awt.Color;
import sas.*;

/**
 * Die Klasse Vogel zeichnet und bewegt den Vogel, der aus einem Rumpf, einem 
 * Schnabel, einem Auge und einem Fluegel besteht.
 * 
 * @author ( Klaus Dingemann) 
 * @version (02.09.2017)
 */

public class Vogel
{
    // Attribute der Klasse Vogel
    Picture vogel;

    public Vogel()
    {   
        vogel = new Picture(50,278,50,44,"birdrotklein.png");
        vogel.flipHorizontal();
    }


    public boolean imSpielfeld() {
         return vogel.getShapeY()<600; 
    }


    public void bewegen(int pDistanz) {
        vogel.move(0,pDistanz);
    }

    public Picture gibPicture() {
        return vogel;
    }

    public void setzeInAusgangsposition() {
      vogel.moveTo(50, 278);
    }
}

import sas.*;
public class Landschaft
{
   Hindernis[] hindernisse;
   int naechstesHindernis;
   Sprite hintergrund1;
   Sprite hintergrund2;


    public Landschaft()
    {
       Picture bild1 = new Picture(0,0,"landschaft.png");
       hintergrund1 = new Sprite(bild1);
       Picture bild2 = new Picture(1600,0,"landschaft.png");
       hintergrund2 = new Sprite(bild2);
       hindernisse = new Hindernis[16];
       for (int i = 0; i < 8; i++) {
          hindernisse[i] = new Hindernis(200*i);
          hintergrund1.add(hindernisse[i].gibBild());
       }
       for (int i = 8; i < 16; i++) {
          hindernisse[i] = new Hindernis(200*i);
          hintergrund2.add(hindernisse[i].gibBild());
       }
       naechstesHindernis = 1;
    }

    public void bewegen(int pDistanz) {
      hintergrund1.move(pDistanz,0);
      hintergrund2.move(pDistanz,0);
      if (hintergrund1.getShapeX()==-1600) {
         hintergrund1.move(3200,0); 
      }    
      if (hintergrund2.getShapeX()==-1600) {
         hintergrund2.move(3200,0); 
      }
    }

    public boolean kollision(Vogel pVogel) {
      boolean koll = false;
      if (hindernisse[naechstesHindernis].kollision(pVogel)) {
              koll = true;
      }
      return koll;
    }

    public boolean hindernisPassiert(Vogel pVogel) {
       boolean pass = hindernisse [naechstesHindernis].durchflogen(pVogel);
       if (pass) {
           naechstesHindernis = (naechstesHindernis + 1) % (16);
       }
       return pass;
    }

    public void setzeInAusgangsposition(){
        hintergrund1.moveTo(0,hintergrund1.getShapeY());
        hintergrund2.moveTo(1600,hintergrund2.getShapeY());
        naechstesHindernis = 1;
    }
 }




/**
 * Die Klasse Roehre stellt die beiden Roehren-Teile als Rectanglee dar, durch 
 * die der Vogel fliegen muss.
 * 
 * @author Klaus Dingemann
 * @version (03.09.2017)
 */
import java.awt.Color;
import sas.*;
public class Hindernis 
{
   private Picture hindernisOben;
   private Picture hindernisUnten;
   private Sprite hindernis;

    /**
     * Erstellt zwei Roehren  - oben und unten
     * 
     * @param x x-Koordinate für die linke obere Ecke der oberen Roehre
     */

    public Hindernis(int pXPosition)
    {
        int oben = Tools.randomNumber(-400,-50);
        hindernisOben = new Picture(pXPosition, oben, 50,450,"rinde.png");
        hindernisUnten = new Picture(pXPosition, oben+600, 50,450,"rinde.png");
        hindernis = new Sprite();
        hindernis.add(hindernisOben);
        hindernis.add(hindernisUnten);
    }

    public Sprite gibBild() {
        return hindernis;
    }

    public boolean kollision(Vogel pVogel) 
    {
        if (hindernisOben.intersects(pVogel.gibPicture()) || 
            hindernisUnten.intersects(pVogel.gibPicture())){
            return true;
        } else {
            return false;
        }
    }

    public boolean durchflogen(Vogel pVogel) {
        return pVogel.gibPicture().getShapeX() > hindernis.getShapeX() + 50;
    }
}
